CREATE   VIEW [synapse_ce].[vwQuote]
AS
SELECT 
	q.[quoteid],
	q.[quotenumber],
	q.[msdyn_quotenumber],
	q.[name],
	q.[description],
	q.[apuk_campaignyear],
	q.[campaignid],
	q.[createdon],
	q.[createdby] AS createdbyID,
	createdby.fullname AS createdby,
	q.[modifiedon],
	q.[modifiedby],
	q.[ownerid],
	q.[apuk_paymentmethod],
	paymethod.[LocalizedLabel] AS [apuk_paymentmethod_description],
	q.[msdyn_salesquotationstatus],
	quotestatus.[LocalizedLabel] AS [msdyn_salesquotationstatus_description],
	q.[msdyn_ordertype],
	q.[apuk_invoicesalesorder],
	q.[apuk_quoteaccepted],
	q.[apuk_paymentreceived],
	q.[apuk_casedrs], --apuk_casedrs
	q.[accountid],
	q.[apuk_enrolmentid],
	q.[apuk_regulatedschemeid],
	q.[apuk_ricsrecordid],
	--q.[apuk_paymentschedule], --msdyn_paymentschedule
	q.[opportunityid],
	q.[msdyn_invoicecustomer], --account
	q.[transactioncurrencyid],
	TC.isocurrencycode AS transaction_currency_code,

	q.[msdyn_isocurrencycode],
	q.[apuk_productsubscriptionid], --apuk_subscription
	q.[apuk_subscriptionid],
	q.[apuk_subscriptionproducttype],
	subprdtype.[LocalizedLabel] AS [apuk_subscriptionproducttype_description],
	q.[customerid], --contact
	q.[msdyn_invoicecustomerid], --contact
	q.[totallineitemamount],
	q.[totallineitemamount_base],
	q.[totallineitemdiscountamount],
	q.[totallineitemdiscountamount_base],
	q.[totalamountlessfreight],
	q.[totalamountlessfreight_base],
	q.[totaldiscountamount],
	q.[totaldiscountamount_base],
	q.[totalamount],
	q.[totalamount_base],
	q.[totaltax],
	q.[totaltax_base],
	q.[apuk_lionheartdonation],
	q.[apuk_lionheartdonation_base],
	q.[exchangerate],
	q.[apuk_totalprofessionalfees],
	q.[apuk_totalprofessionalfees_base],
	q.[apuk_purchaseordernumber],
	q.[closedon],
	q.[apuk_subscriptionstartdate],
	q.[apuk_subscriptionenddate],
	q.[requestdeliveryby],
	q.[msdyn_quotelinestartdate],
	q.[msdyn_quotelineenddate],
	q.[statecode],
	stStateCode.[LocalizedLabel] AS [StateCode_Description],
	q.[statuscode],
	stStatusCode.[LocalizedLabel] AS [StatusCode_Description],
	q.[apuk_billto], -- ContactId

		q.msdyn_company, 
	q.msdyn_url, 
	q.apuk_tribunalid, 
	q.msdyn_totalamount_base, 
	q.msdyn_totalamount, 
	q.msdyn_totalnonchargeablecostrollup_base, 
	q.msdyn_totalnonchargeablecostrollup, 
	q.msdyn_totaldiscountpercentage, 
	q.msdyn_totalchargeablecostrollup_base, 
	q.msdyn_totalchargeablecostrollup, 
	q.slaid, 
	q.apuk_showonportal, 
	q.shippingmethodcode, 
	q.shipto_postalcode, 
	q.shipto_line3, 
	q.shipto_line2, 
	q.shipto_line1, 
	q.shipto_stateorprovince, 
	q.shipto_telephone, 
	q.shipto_name, 
	q.shipto_freighttermscode, 
	q.shipto_fax, 
	q.shipto_country, 
	q.shipto_contactname, 
	q.shipto_city, 
	q.shipto_composite, 
	q.willcall, 
	q.apuk_sanctionid, 
	q.msdyn_salesquotationfollowupdate, 
	q.msdyn_salesquotationexpirydate, 
	q.msdyn_salesquotationconfirmationdate, 
	q.msdyn_salesorderpromisingmethod, 
	q.revisionnumber, 
	q.apuk_revenueschedule, 

	q.msdyn_requestedreceiptdate, 
	q.overriddencreatedon, 
	q.discountamount_base, 
	q.discountamount, 
	q.discountpercentage, 
	q.apuk_quoteid, 
	q.msdyn_profitability, 
	q.processid, 
	q.pricelevelid, 
	q.msdyn_pricecustomergroup, 
	q.msdyn_account, 
	q.apuk_paymenttermsbasedate, 
	q.msdyn_paymentterms, 
	q.paymenttermscode, 
	q.apuk_paymentschedule, 
	q.apuk_paymentrequestid, 
	q.owningbusinessunit, 
	q.msdyn_operatingunit, 
	q.onholdtime, 
	q.apuk_numberoflatefees, 
	q.apuk_newquoteneeded, 
	q.modifiedonbehalfby, 
	q.lastonholdtime, 
	q.msdyn_language, 
	q.apuk_isonlineenrolment, 
	q.msdyn_isinvoiceaddressprivate, 
	q.msdyn_isdeliveryaddressprivate, 
	q.msdyn_isdeliveryaddressorderspecific, 
	q.msdyn_invoicesetuptotals_base, 
	q.msdyn_invoicesetuptotals, 
	q.msdyn_invoicebuildingcompliment, 
	q.msdyn_invoiceaddresspostbox, 
	q.msdyn_invoiceaddresslongitude, 
	q.msdyn_invoiceaddresslatitude, 
	q.msdyn_invoiceaddressdistrictname, 
	q.msdyn_invoiceaddresscountyid, 
	q.msdyn_invoiceaddresscountryregionid, 
	q.msdyn_grossmargin, 
	q.msdyn_generatedsalesordernumber, 
	q.freighttermscode, 
	q.freightamount_base, 
	q.freightamount, 
	q.msdyn_formattedinvoiceaddress, 
	q.msdyn_formatteddeliveryaddress, 
	q.apuk_feetype, 
	q.msdyn_feasible, 
	q.msdyn_estimatedschedule, 
	q.msdyn_estimatedquotemargin, 
	q.msdyn_estimatedcost_base, 
	q.msdyn_estimatedcost, 
	q.msdyn_estimatedcompletionrollup, 
	q.msdyn_estimatedbudget, 
	q.emailaddress, 
	q.effectiveto, 
	q.effectivefrom, 
	q.expireson, 
	q.apuk_discountapproval, 
	q.apuk_directdebitfees_base, 
	q.apuk_directdebitfees, 
	q.msdyn_deliverybuildingcompliment, 
	q.msdyn_deliveryaddresspostbox, 
	q.msdyn_deliveryaddressname, 
	q.msdyn_deliveryaddresslongitude, 
	q.msdyn_deliveryaddresslocationid, 
	q.msdyn_deliveryaddresslatitude, 
	q.msdyn_deliveryaddressdunsnumber, 
	q.msdyn_deliveryaddressdistrictname, 
	q.msdyn_deliveryaddressdescription, 
	q.msdyn_deliveryaddresscountyid, 
	q.msdyn_defaultshippingwarehouse, 
	q.msdyn_defaultshippingsite, 
	q.msdyn_customersreference, 
	q.msdyn_customerrequisitionnumber, 
	q.apuk_customernameid, 
	q.apuk_customercompanyid, 
	q.msdyn_customerbudgetrollup_base, 
	q.msdyn_customerbudgetrollup, 
	q.createdonbehalfby, 
	q.apuk_corppaymentref, 
	q.msdyn_contractorganizationalunitid, 
	q.msdyn_contactperson, 
	q.msdyn_competitive, 
	q.msdyn_cashdiscountpercentage, 
	q.billto_postalcode, 
	q.billto_line3, 
	q.billto_line2, 
	q.billto_line1, 
	q.billto_stateorprovince, 
	q.billto_telephone, 
	q.billto_name, 
	q.billto_fax, 
	q.billto_country, 
	q.billto_contactname, 
	q.billto_city, 
	q.billto_composite, 
	q.msdyn_arepricesincludingsalestax, 
	q.msdyn_adjustedgrossmargin, 
	q.msdyn_accountmanagerid, 
	q.stageid
FROM synapse_ce.quote q
	LEFT JOIN synapse_ce.GlobalOptionSetMetadata paymethod
		ON q.[apuk_paymentmethod] = paymethod.[Option]
			AND paymethod.[OptionSetName] = 'apuk_paymentmethod'
			AND paymethod.[EntityName] = 'quote'
	LEFT JOIN synapse_ce.GlobalOptionSetMetadata quotestatus
		ON q.[msdyn_salesquotationstatus] = quotestatus.[Option]
			AND quotestatus.[OptionSetName] = 'msdyn_salesquotationstatus'
			AND quotestatus.[EntityName] = 'quote'
	LEFT JOIN synapse_ce.GlobalOptionSetMetadata subprdtype
		ON q.[apuk_subscriptionproducttype] = subprdtype.[Option]
			AND subprdtype.[OptionSetName] = 'apuk_subscriptionproducttype'
			AND subprdtype.[EntityName] = 'quote'
	LEFT JOIN synapse_ce.StateMetadata stStateCode
		ON q.[statecode] = stStateCode.[State]
			AND stStateCode.[EntityName] = 'quote' 
	LEFT JOIN synapse_ce.StatusMetadata stStatusCode
		ON q.[statuscode] = stStatusCode.[Status]
			AND stStatusCode.[EntityName] = 'quote'
	LEFT JOIN synapse_ce.transactioncurrency TC
		ON TC.transactioncurrencyid = q.transactioncurrencyid
	LEFT JOIN synapse_ce.systemuser createdby
		ON q.[createdby] = createdby.[systemuserid]
	WHERE NOT EXISTS (
		SELECT contactid
		FROM CE.tblContact_Test_Records TST
		WHERE TST.contactid = q.[customerid]
		OR TST.contactid = q.[msdyn_invoicecustomerid]
		OR TST.contactid = q.[apuk_billto]
		)
